require_once __DIR__.'/../includes/functions.php';require_role(['patient']);$u=current_user();$p=patient_for_user($u['id']);if(!$p){http_response_code(403);exit('Your patient profile is not linked to this account. Contact clinic staff.');}$s=db()->prepare("SELECT a.*,du.name doctor_name,dep.name department_name FROM appointments a JOIN doctors d ON d.id=a.doctor_id JOIN users du ON du.id=d.user_id JOIN departments dep ON dep.id=d.department_id WHERE a.patient_id=? ORDER BY a.appointment_date DESC,a.start_at DESC LIMIT 100");$s->execute([$p['id']]);$rows=$s->fetchAll();$pageTitle='My patient portal';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/page.php';page_heading('Personal health','Welcome, '.current_user()['name'],'Patient ID: '.$p['patient_number'],'<a class="btn btn-primary" href="'.e(url('appointments/book.php')).'"><i class="bi bi-calendar-plus me-1"></i>Book consultation</a>');?>
<div class="row g-3 mb-4"><div class="col-md-4"><?=stat_card('Appointments',(string)count($rows),'calendar-check','Your booking history')?></div><div class="col-md-4"><?=stat_card('Upcoming',(string)count(array_filter($rows,fn($a)=>$a['appointment_date']>=date('Y-m-d')&&!in_array($a['status'],['cancelled','completed','no_show'],true))),'calendar-event','Pending or confirmed')?></div><div class="col-md-4"><?=stat_card('Medical records',(string)(function()use($p){$s=db()->prepare('SELECT COUNT(*) FROM medical_records WHERE patient_id=?');$s->execute([$p['id']]);return (int)$s->fetchColumn();})(),'file-medical','Available in your portal')?></div></div><div class="card"><div class="card-header d-flex justify-content-between"><h2 class="section-title">My appointments</h2><a href="<?=e(url('appointments/index.php'))?>" class="small text-decoration-none">View all</a></div><div class="table-responsive"><table class="table"><thead><tr><th>Doctor</th><th>Department</th><th>Date</th><th>Time</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $a):?><tr><td><strong><?=e($a['doctor_name'])?></strong></td><td><?=e($a['department_name'])?></td><td><?=e($a['appointment_date'])?></td><td><?=e(substr($a['start_at'],0,5))?></td><td><?=status_badge($a['status'])?></td></tr><?php endforeach;?><?php if(!$rows)echo empty_row(5,'You have no appointments yet.');?></tbody></table></div></div><?php require __DIR__.'/../includes/footer.php';?>